import java.util.*;class Solution{public int[] topKFrequent(int[]a,int k){Map<Integer,Integer>m=new HashMap<>();for(int x:a)m.merge(x,1,Integer::sum);List<Integer>[]b=new List[a.length+1];for(var e:m.entrySet()){int c=e.getValue();if(b[c]==null)b[c]=new ArrayList<>();b[c].add(e.getKey());}int[]o=new int[k];int p=0;for(int i=b.length-1;i>=0&&p<k;i--)if(b[i]!=null)for(int x:b[i]){o[p++]=x;if(p==k)break;}return o;}}
